{
  "findings": [
    {
      "check_id": "CKV_AWS_5",
      "title": "Ensure all data stored in the Elasticsearch is securely encrypted at rest",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' has 'encrypt_at_rest' set to false, leaving data unencrypted at rest."
    },
    {
      "check_id": "CKV_AWS_6",
      "title": "Ensure all Elasticsearch has node-to-node encryption enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' is missing 'node_to_node_encryption' configuration, which is a security risk if not enabled."
    },
    {
      "check_id": "CKV_AWS_228",
      "title": "Verify Elasticsearch domain is using an up to date TLS policy",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' is missing 'domain_endpoint_options' configuration, which includes the TLS security policy."
    },
    {
      "check_id": "CKV_AWS_318",
      "title": "Ensure Elasticsearch domains are configured with at least three dedicated master nodes for HA",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' has 'instance_count' set to 2 and lacks dedicated master nodes configuration, potentially compromising high availability."
    },
    {
      "check_id": "CKV2_AWS_59",
      "title": "Ensure ElasticSearch/OpenSearch has dedicated master node enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' lacks 'dedicated_master_enabled' configuration, which is necessary for a robust cluster setup."
    }
  ],
  "patched_code": "resource \"aws_elasticsearch_domain\" \"log_search_database\" {\n  domain_name           = \"enterprise-log-analytics-es\"\n  elasticsearch_version = \"7.10\"\n  cluster_config {\n    instance_type  = var.elasticsearch_instance_type\n    instance_count = 3\n    dedicated_master_enabled = true\n    dedicated_master_count = 3\n    dedicated_master_type = var.elasticsearch_instance_type\n  }\n  vpc_options {\n    subnet_ids         = [aws_subnet.data_subnet_az1.id]\n    security_group_ids = [aws_security_group.elasticsearch_sg.id]\n  }\n  ebs_options {\n    ebs_enabled = true\n    volume_size = 20\n    volume_type = \"gp2\"\n  }\n  encrypt_at_rest {\n    enabled = true\n  }\n  node_to_node_encryption {\n    enabled = true\n  }\n  domain_endpoint_options {\n    tls_security_policy = \"Policy-Min-TLS-1-2-2019-07\"\n  }\n}",
  "fix_summary": "Enabled encryption at rest, node-to-node encryption, and updated TLS security policy. Configured dedicated master nodes for high availability and set instance count to 3."
}
